What does this log?
```js
const log = console.log;
const fail = async () => { throw 'x'; };
async function load() {
  try {
    return fail();
  } catch {
    return 'fallback';
  }
}
load().then(log, (e) => log('rejected', e));
```

In an ES module, what does this log?
```js
const fail = async () => { throw 'x'; };
async function a() {
  try { return fail(); }
  catch { return 'A'; }
}
async function b() {
  try { return await fail(); }
  catch { return 'B'; }
}
const all = [a(), b()];
const r = await Promise.allSettled(all);
const out = r.map((s) => s.value ?? s.reason);
console.log(...out);
```

What does this log?
```js
const log = console.log;
process.on('unhandledRejection', (e) => {
  log('unhandled', e);
});
const fail = async () => { throw 'x'; };
async function load() {
  try {
    fail();
    return 'ok';
  } catch {
    return 'fallback';
  }
}
load().then(log);
```

What does this log in Node?
```js
const log = console.log;
process.on('unhandledRejection', (e) => {
  log('unhandled', e);
});
const wait = (ms, ok) => new Promise((r, j) =>
  setTimeout(() => (ok ? r() : j('E')), ms));
(async () => {
  const slow = wait(20, true);
  const fast = wait(10, false);
  try {
    await slow;
    await fast;
  } catch (e) {
    log('caught', e);
  }
})();
```

What does this log in Node?
```js
const log = console.log;
process.on('unhandledRejection', (e) => {
  log('unhandled', e);
});
const wait = (ms, ok) => new Promise((r, j) =>
  setTimeout(() => (ok ? r() : j('E')), ms));
(async () => {
  const slow = wait(20, true);
  const fast = wait(10, false);
  try {
    await Promise.all([slow, fast]);
  } catch (e) {
    log('caught', e);
  }
})();
```
